import { readFileSync, writeFileSync } from 'node:fs';
import { expect, it } from 'vitest';
import { parseCatalogCsv } from '../../packages/infrastructure/src/catalog-csv';
it('diagnoses mixed record delimiters using copies, keeping pinned inputs unchanged', () => {
 const results = ['catalog_converted.csv','catalog_converted-previous.csv','catalog_converted-normalized-diagnostic.csv'].map(file=>({file,...parseCatalogCsv(readFileSync(`.runtime/c06-a1313/${file}`,'utf8'))}));
 writeFileSync('.runtime/c06-a1313/delimiter-diagnosis.json',JSON.stringify(results.map(r=>({file:r.file,rows:r.rows.length,issues:r.issues})),null,2));
 expect(results[0]!.issues.length).toBeGreaterThan(0);
 expect(results[1]!.issues).toEqual([]);
 expect(results[2]!.issues).toEqual([]);
 expect(results[2]!.rows).toHaveLength(286);
});
